"""Probe opencode.db part/message data shapes — read-only."""
import json
import os
import sqlite3
import sys

sys.stdout.reconfigure(encoding="utf-8")

DB = os.path.join(os.path.expanduser("~"), ".local", "share", "opencode", "opencode.db")
con = sqlite3.connect(f"file:{DB}?mode=ro", uri=True)
cur = con.cursor()

# ── part types ──
print("=== part.data.type distribution ===")
rows = cur.execute("SELECT data FROM part").fetchall()
types = {}
samples = {}
for (data,) in rows:
    try:
        d = json.loads(data)
    except Exception:
        types["<unparseable>"] = types.get("<unparseable>", 0) + 1
        continue
    t = d.get("type", "<none>")
    types[t] = types.get(t, 0) + 1
    if t not in samples:
        samples[t] = d
for t, n in sorted(types.items(), key=lambda x: -x[1]):
    print(f"  {t}: {n}")
    if t in samples:
        s = json.dumps(samples[t], ensure_ascii=False)
        print(f"    sample: {s[:300]}")

# ── message roles ──
print("\n=== message.data.role distribution ===")
roles = {}
msamples = {}
for (data,) in cur.execute("SELECT data FROM message").fetchall():
    try:
        d = json.loads(data)
    except Exception:
        roles["<unparseable>"] = roles.get("<unparseable>", 0) + 1
        continue
    r = d.get("role", "<none>")
    roles[r] = roles.get(r, 0) + 1
    if r not in msamples:
        msamples[r] = d
for r, n in sorted(roles.items(), key=lambda x: -x[1]):
    print(f"  {r}: {n}")
    if r in msamples:
        s = json.dumps(msamples[r], ensure_ascii=False)
        print(f"    sample: {s[:300]}")

# ── part types per role (join) ──
print("\n=== part type x message role ===")
rows = cur.execute("""
    SELECT m.data, p.data FROM part p JOIN message m ON p.message_id = m.id
""").fetchall()
cross = {}
for mdata, pdata in rows:
    try:
        md = json.loads(mdata)
        pd = json.loads(pdata)
    except Exception:
        continue
    key = (md.get("role"), pd.get("type"))
    cross[key] = cross.get(key, 0) + 1
for (role, ptype), n in sorted(cross.items(), key=lambda x: -x[1]):
    print(f"  {role} / {ptype}: {n}")

con.close()
